"""Home-turf validation: data generated by a Markov-switching rotation on a torus.

The generative process is exactly the model's inductive bias:

  - a hidden discrete regime s_t follows a Markov chain (K states, sticky);
  - each regime rotates a d-dimensional phase vector at its own angular
    velocity:  theta_{t+1} = wrap(theta_t + omega_{s_t});
  - the observation is a noisy phase readout:  x_t = amp * sin(theta_t) + eps.

Predicting the next H observations therefore requires jointly tracking the
phases and the latent regime.  If the toric architecture cannot beat generic
sequence models on data produced by its own assumptions, it should not be
applied anywhere else.  Conversely, a win here is the *evidence* that
justifies trying it on real cyclic data.

Usage (repository root)::

    python -m research.synthetic_torus --models mmt,gru,lstm,transformer,dlinear,naive
"""

from __future__ import annotations

import argparse
import json
import math
from pathlib import Path

import numpy as np
import torch
from torch import nn

from .baselines import (
    DLinearForecaster,
    RecurrentForecaster,
    TransformerForecaster,
    drift_forecast,
    persistence_forecast,
)
from .toric_core import HybridForecaster, ToricForecaster, markov_agreement
from .train_utils import (
    count_parameters,
    evaluate,
    evaluate_naive,
    train_hybrid_residual,
    train_model,
)


def simulate_switching_rotation(
    n_sequences: int,
    length: int,
    num_dims: int = 8,
    num_states: int = 4,
    noise_std: float = 0.1,
    speed_scale: float = 1.0,
    seed: int = 7,
) -> tuple[np.ndarray, np.ndarray]:
    """Simulate the Markov-switching phase process; returns x (N, len, d), s (N, len)."""
    generator = torch.Generator().manual_seed(seed)
    # Distinct angular-velocity regimes: rows are a shared random direction
    # scaled by clearly different speeds, so regimes are identifiable in principle.
    direction = torch.randn(num_states, num_dims, generator=generator)
    direction = direction / direction.norm(dim=-1, keepdim=True)
    speeds_scale = torch.tensor([0.06, 0.13, 0.22, 0.33]) * speed_scale
    omega = direction * speeds_scale[:num_states].unsqueeze(1)

    # Sticky transition matrix: 90% stay, uniform elsewhere.
    transition = torch.full((num_states, num_states), 0.1 / (num_states - 1))
    transition.fill_diagonal_(0.9)

    amplitude = 0.5 + torch.rand(num_dims, generator=generator)  # [0.5, 1.5]
    theta = (torch.rand(n_sequences, num_dims, generator=generator) * 2 - 1) * math.pi
    states = torch.zeros(n_sequences, dtype=torch.long)
    obs = torch.empty(n_sequences, length, num_dims)
    states_history = torch.empty(n_sequences, length, dtype=torch.long)

    for t in range(length):
        states_history[:, t] = states
        obs[:, t] = amplitude * torch.sin(theta) + noise_std * torch.randn(
            n_sequences, num_dims, generator=generator
        )
        rows = transition[states]
        states = torch.multinomial(rows, 1, generator=generator).squeeze(-1)
        theta = theta + omega[states]

    return obs.numpy().astype(np.float32), states_history.numpy()


def build_model(name: str, num_features: int, seq_len: int, horizon: int, args) -> nn.Module:
    toric_kwargs = dict(
        dim_angles=args.dim,
        num_levels=2,
        num_states=args.states,
        num_layers=1,
        kernel=args.kernel,
        use_attention=True,
        use_amplitude=args.amplitude,
        use_diff_input=args.diff_input,
        quantize_positions=not args.no_quant,
        n_bits=16 if args.no_quant else 8,  # 16 bits ~ effectively unquantized grid
    )
    if name in ("mmt", "hybrid", "hybrid_res"):
        if name == "mmt":
            return ToricForecaster(num_features, horizon, **toric_kwargs)
        return HybridForecaster(num_features, seq_len, horizon, **toric_kwargs)
    if name in ("gru", "lstm"):
        return RecurrentForecaster(
            num_features, horizon, kind=name,
            hidden_dim=args.hidden, use_diff_input=args.diff_input,
        )
    if name == "transformer":
        return TransformerForecaster(
            num_features, horizon, d_model=args.hidden, use_diff_input=args.diff_input,
        )
    if name == "dlinear":
        return DLinearForecaster(seq_len, horizon)
    raise ValueError(f"unknown model {name!r}")


NAIVE_PREDICTORS = {
    "persistence": persistence_forecast,
    "drift": drift_forecast,
}


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--n-train", type=int, default=2500)
    parser.add_argument("--n-val", type=int, default=600)
    parser.add_argument("--n-test", type=int, default=600)
    parser.add_argument("--seq", type=int, default=64)
    parser.add_argument("--horizon", type=int, default=12)
    parser.add_argument("--epochs", type=int, default=6)
    parser.add_argument("--batch", type=int, default=64)
    parser.add_argument("--lr", type=float, default=2e-3)
    parser.add_argument("--patience", type=int, default=2)
    parser.add_argument("--dim", type=int, default=48, help="toric angle dimension")
    parser.add_argument("--states", type=int, default=24, help="toric states")
    parser.add_argument("--hidden", type=int, default=64, help="baseline width")
    parser.add_argument("--speed-scale", type=float, default=1.0,
                        help="multiplier on regime angular speeds (harder task)")
    parser.add_argument("--kernel", type=str, default="stochastic", choices=("stochastic", "free"))
    parser.add_argument("--no-quant", action="store_true",
                        help="use a 16-bit phase grid (effectively unquantized)")
    parser.add_argument("--amplitude", action="store_true",
                        help="enable the toric encoder amplitude bypass")
    parser.add_argument("--diff-input", action="store_true",
                        help="append first differences to the model inputs")
    parser.add_argument("--curriculum", action="store_true",
                        help="mmt only: warm up on half-speed rotations first")
    parser.add_argument("--base-epochs", type=int, default=10,
                        help="linear-base epochs for hybrid_res phase 1")
    parser.add_argument("--seed", type=int, default=0)
    parser.add_argument("--models", type=str, default="mmt,gru,lstm,transformer,dlinear,naive")
    parser.add_argument("--out", type=str, default="research/results_synthetic.json")
    args = parser.parse_args()

    torch.manual_seed(args.seed)
    np.random.seed(args.seed)
    length = args.seq + args.horizon
    print(f"Simulating switching-rotation data (length={length}, d=8, K=4)...")
    x_all, s_all = simulate_switching_rotation(
        args.n_train + args.n_val + args.n_test, length, speed_scale=args.speed_scale
    )
    n_train, n_val = args.n_train, args.n_val
    # Each simulated sequence already spans exactly seq + horizon steps.
    train_x = torch.from_numpy(x_all[:n_train, : args.seq])
    train_y = torch.from_numpy(x_all[:n_train, args.seq :])
    val_x = torch.from_numpy(x_all[n_train : n_train + n_val, : args.seq])
    val_y = torch.from_numpy(x_all[n_train : n_train + n_val, args.seq :])
    test_x = torch.from_numpy(
        x_all[n_train + n_val : n_train + n_val + args.n_test, : args.seq]
    )
    test_y = torch.from_numpy(
        x_all[n_train + n_val : n_train + n_val + args.n_test, args.seq :]
    )
    # True regime at the last observed step, for the interpretability check.
    true_last_state = torch.from_numpy(
        s_all[n_train + n_val : n_train + n_val + args.n_test, args.seq - 1].astype(np.int64)
    )

    print(
        f"windows: train {tuple(train_x.shape)}, val {tuple(val_x.shape)},"
        f" test {tuple(test_x.shape)}\n"
    )

    results = {"config": vars(args), "models": {}}
    requested = [m.strip() for m in args.models.split(",") if m.strip()]
    run_neural = [m for m in requested if m not in ("naive",)]
    run_naive = "naive" in requested or any(m in NAIVE_PREDICTORS for m in requested)

    for name in run_neural:
        model = build_model(name, train_x.shape[-1], args.seq, args.horizon, args)
        params = count_parameters(model)
        print(f"[{name}] params={params:,}")
        if name == "hybrid_res":
            outcome = train_hybrid_residual(
                model, train_x, train_y, val_x, val_y,
                base_epochs=args.base_epochs, residual_epochs=args.epochs,
                batch_size=args.batch, lr=args.lr, patience=args.patience,
                seed=args.seed,
            )
        elif name == "mmt" and args.curriculum:
            # Stage 1: half-speed rotations (easier phase tracking), then the
            # real task.  Validation always measures the real task.
            stage_obs, _ = simulate_switching_rotation(
                args.n_train, length, speed_scale=args.speed_scale * 0.5,
                seed=args.seed + 100,
            )
            easy_x = torch.from_numpy(stage_obs[:, : args.seq])
            easy_y = torch.from_numpy(stage_obs[:, args.seq :])
            outcome_stage1 = train_model(
                model, easy_x, easy_y, val_x, val_y,
                epochs=args.epochs // 2, batch_size=args.batch, lr=args.lr,
                patience=args.patience, seed=args.seed,
            )
            outcome_stage2 = train_model(
                model, train_x, train_y, val_x, val_y,
                epochs=args.epochs - args.epochs // 2, batch_size=args.batch,
                lr=args.lr, patience=args.patience, seed=args.seed,
            )
            outcome = {
                "model": model,
                "history": outcome_stage1["history"] + outcome_stage2["history"],
                "best_val_mse": outcome_stage2["best_val_mse"],
            }
        else:
            outcome = train_model(
                model, train_x, train_y, val_x, val_y,
                epochs=args.epochs, batch_size=args.batch, lr=args.lr,
                patience=args.patience, seed=args.seed,
            )
        test_mse, test_mae = evaluate(outcome["model"], test_x, test_y)
        entry = {
            "params": params,
            "best_val_mse": round(outcome["best_val_mse"], 5),
            "test_mse": round(test_mse, 5),
            "test_mae": round(test_mae, 5),
        }
        if name == "mmt" and args.states == 4:
            # Interpretability check: with exactly as many chain states as true
            # regimes, does the unsupervised chain recover them (up to labels)?
            _, probs = outcome["model"](test_x[:512], return_state=True)
            entry["state_agreement_vs_true_regime"] = round(
                markov_agreement(true_last_state[:512], probs, 4), 4
            )
        results["models"][name] = entry
        print(f"[{name}] test mse={test_mse:.4f} mae={test_mae:.4f}\n")

    if run_naive:
        for name, fn in NAIVE_PREDICTORS.items():
            if name not in requested and "naive" not in requested:
                continue
            mse, mae = evaluate_naive(lambda xb: fn(xb, args.horizon), test_x, test_y)
            results["models"][name] = {"params": 0, "test_mse": round(mse, 5), "test_mae": round(mae, 5)}
            print(f"[{name}] test mse={mse:.4f} mae={mae:.4f}")

    out_path = Path(args.out)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(results, indent=2))

    print("\n=== Summary (standardized-scale MSE, lower is better) ===")
    ranked = sorted(results["models"].items(), key=lambda kv: kv[1]["test_mse"])
    for name, entry in ranked:
        extra = f"  params={entry['params']:,}" if entry.get("params") else ""
        agree = entry.get("state_agreement_vs_true_regime")
        suffix = f"  regime-agreement={agree}" if agree is not None else ""
        print(f"  {name:<12} mse={entry['test_mse']:.4f}  mae={entry['test_mae']:.4f}{extra}{suffix}")
    print(f"\nsaved: {out_path}")


if __name__ == "__main__":
    main()
